// VOICE ACTING — the same line, delivered in different ways, means different things.
// Each delivery is generated by the AI voice with its own acting instructions (see server TONES),
// never by just changing the speed. To add lines: append to LINES.
import type { Cefr } from './types';
import type { Tone } from '../services/api';

export interface Delivery {
  id: string;
  /** Acting direction sent to the TTS provider. */
  tone: Tone;
  /** The intention, as shown in the answers (English). */
  intent: string;
  /** Short Spanish gloss of the intention. */
  es: string;
  /** Why this delivery changes the meaning (Spanish from Spain). */
  explain: string;
}

export interface VoiceLine {
  id: string;
  text: string;
  level: Cefr;
  /** Short situation that makes the line plausible (Spanish), shown only after answering. */
  context: string;
  deliveries: Delivery[];
  /** A plausible wrong intention that no delivery uses. */
  decoy: string;
}

