export const LINE_BY_ID: Record<string, VoiceLine> = Object.fromEntries(LINES.map((l) => [l.id, l]));
/** A review item is one line + one delivery. */
export const roundId = (lineId: string, deliveryId: string) => `${lineId}:${deliveryId}`;
export function parseRound(id: string) {
  const [lineId, deliveryId] = id.split(':');
  const line = LINE_BY_ID[lineId];
  const delivery = line?.deliveries.find((d) => d.id === deliveryId);
  return line && delivery ? { line, delivery } : null;
}
